from quant_system.factors.base import BaseFactor


class PaperReversalMomentumProxyV2(BaseFactor):
    factor_id = "paper_reversal_momentum_proxy_v2"
    factor_name = "Paper Reversal Momentum Proxy V2"
    factor_version = "0.2.0"
    default_lookback = 252
    direction = "higher_is_better"
    description = (
        "Operational US-ETF workflow proxy inspired by DOI "
        "10.1093/rfs/hhaf057: one-month reversal plus months t-12 through "
        "t-2 momentum. It is not a full country-level paper replication."
    )

    def _compute_values(self, frame):
        close = frame.groupby("symbol", sort=False)["close"]
        one_month_return = close.pct_change(21, fill_method=None)
        price_t_minus_1m = close.shift(21)
        price_t_minus_12m = close.shift(252)
        momentum_12_2 = price_t_minus_1m / price_t_minus_12m - 1.0
        return -one_month_return + momentum_12_2
